<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class Invoice extends Model { protected $fillable=['service_request_id','quotation_id','number','issued_at','due_at','currency','subtotal','discount','tax','total','amount_paid','status','notes','terms']; protected $casts=['issued_at'=>'date','due_at'=>'date','subtotal'=>'decimal:2','discount'=>'decimal:2','tax'=>'decimal:2','total'=>'decimal:2','amount_paid'=>'decimal:2']; protected static function booted(){static::creating(function(self $m){$m->number??='INV-'.now()->year.'-'.str_pad((string)(self::whereYear('created_at',now()->year)->count()+1),6,'0',STR_PAD_LEFT);}); static::saving(fn(self $m)=>$m->recalculate());} public function recalculate():void{$this->subtotal=$this->items->sum(fn($i)=>($i->quantity*$i->unit_price)-$i->discount);$this->total=max(0,$this->subtotal-$this->discount+$this->tax);$paid=$this->payments()->where('status','completed')->sum('amount');$this->amount_paid=$paid;$this->status=$paid<=0?($this->status==='void'?'void':'issued'):($paid<$this->total?'partially_paid':'paid');} public function getBalanceDueAttribute(){return max(0,(float)$this->total-(float)$this->amount_paid);} public function request(){return $this->belongsTo(ServiceRequest::class,'service_request_id');} public function quotation(){return $this->belongsTo(Quotation::class);} public function items(){return $this->hasMany(InvoiceItem::class);} public function payments(){return $this->hasMany(Payment::class);} }
